import React from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import Navbar from './components/Navbar';
import Informatica from './pages/Informatica';
import Idiomas from './pages/Idiomas';
import FP from './pages/FP';
import InfantilPrimaria from './pages/InfantilPrimaria';

function App() {
  return (
    <Router>
      <Navbar />
      <Switch>
        <Route path="/informatica" component={Informatica} />
        <Route path="/idiomas" component={Idiomas} />
        <Route path="/fp" component={FP} />
        <Route path="/infantil-primaria" component={InfantilPrimaria} />
        <Route path="/" exact>
          <h1>Bienvenido a la aplicación de cursos</h1>
        </Route>
      </Switch>
    </Router>
  );
}

export default App;
